+// API keys and the audit log. Keys live in the store as
+// apiKeys [{ key, name, role }]; audit entries are only ever appended.
+import { createHash, timingSafeEqual } from "node:crypto";
+
+const digest = (s) => createHash("sha256").update(String(s)).digest();
+
+/** The API key record for `key` ({ key, name, role }), or null. */
+export function findKey(store, key) {
+  if (typeof key !== "string" || key === "") return null;
+  const d = digest(key);
+  return (store.data.apiKeys ?? []).find((k) => timingSafeEqual(digest(k.key), d)) ?? null;
+}
+
+/** Appends an audit entry { at, keyName, method, path, status }. */
+export function recordAudit(store, { at, keyName, method, path, status }) {
+  store.data.audit ??= [];
+  const entry = { at, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return (store.data.audit ?? []).slice().reverse();
+}
