+// Who may call what. Requests carry `Authorization: Bearer <key>`; the key's
+// role decides: viewer reads, cook also does kitchen work, manager does all.
+
+const COOK_ROUTES = new Set([
+  "POST /recipes/:id/cook",
+  "POST /batches/:id/waste",
+  "POST /temperatures",
+  "POST /stocktakes/:id/counts",
+]);
+const MANAGER_ONLY = new Set(["GET /audit"]);
+
+/** The key from an `Authorization: Bearer <key>` header, or null. */
+export function bearerKey(headers) {
+  const name = Object.keys(headers ?? {}).find((h) => h.toLowerCase() === "authorization");
+  const m = /^Bearer\s+(\S+)\s*$/i.exec(name ? String(headers[name]) : "");
+  return m ? m[1] : null;
+}
+
+/** Whether `role` may call `route` ("METHOD /pattern"). */
+export function allowed(role, method, route) {
+  if (role === "manager") return true;
+  if (role !== "viewer" && role !== "cook") return false;
+  if (MANAGER_ONLY.has(route)) return false;
+  if (method === "GET") return true;
+  return role === "cook" && COOK_ROUTES.has(route);
+}
