diff --git a/tests/auth.test.js b/tests/auth.test.js
new file mode 100644
index 0000000..86d4c80
--- /dev/null
+++ b/tests/auth.test.js
@@ -0,0 +1,55 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, fresh, KEYS } from "./helpers.js";
+
+test("no key or an unknown key is 401", async () => {
+  const { raw } = app();
+  const none = await raw({ path: "/items" });
+  assert.equal(none.status, 401);
+  assert.equal(none.body.error.code, "unauthorized");
+  const wrong = await raw({ path: "/items", headers: { authorization: "Bearer nope" } });
+  assert.equal(wrong.status, 401);
+  const basic = await raw({ path: "/items", headers: { Authorization: `Basic ${KEYS.manager}` } });
+  assert.equal(basic.status, 401);
+});
+
+test("a viewer may only read", async () => {
+  const { handle, store } = app(fresh(), KEYS.viewer);
+  assert.equal((await handle({ path: "/items" })).status, 200);
+  const before = JSON.stringify(store.data.batches);
+  const cook = await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  assert.equal(cook.status, 403);
+  assert.equal(cook.body.error.code, "forbidden");
+  assert.equal(JSON.stringify(store.data.batches), before);
+  assert.equal((await handle({ path: "/audit" })).status, 403);
+});
+
+test("a cook does kitchen work but not management", async () => {
+  const { handle } = app(fresh(), KEYS.cook);
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/batches/6/waste", body: { qty: 0.5 } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/temperatures", body: { location: "fridge", celsius: 3 } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).status, 403);
+  assert.equal((await handle({ method: "POST", path: "/orders", body: { supplierId: 1, lines: [] } })).status, 403);
+  assert.equal((await handle({ path: "/audit" })).status, 403);
+});
+
+test("a cook enters stock-take counts that a manager started", async () => {
+  const store = fresh();
+  const take = (await app(store).handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).body;
+  const res = await app(store, KEYS.cook).handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, body: { batchId: 6, counted: 12 } });
+  assert.equal(res.status, 200);
+});
+
+test("changes are audited, newest first, for managers", async () => {
+  const store = fresh();
+  await app(store, KEYS.cook).handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  await app(store, KEYS.viewer).handle({ method: "POST", path: "/jobs/nightly" });
+  await app(store, KEYS.viewer).handle({ path: "/items" });
+  await app(store).raw({ method: "POST", path: "/jobs/nightly" });
+  const list = (await app(store).handle({ path: "/audit" })).body;
+  assert.deepEqual(list, [
+    { at: "2026-10-28T10:00:00.000Z", keyName: "viewer", method: "POST", path: "/jobs/nightly", status: 403 },
+    { at: "2026-10-28T10:00:00.000Z", keyName: "cook", method: "POST", path: "/recipes/1/cook", status: 200 },
+  ]);
+});
